/// <summary>
/// Product Root Category commitment type for agreement line search.
/// </summary>
public class METAgreementLineSearchCommitmentType_ValueCommitment extends METAgreementLineSearchCommitmentType
{
}

Method.Source:
/// <summary>
/// Setting range to category field to not 0
/// </summary>
/// <param name = "_agreementLineQbds">agreementLineQbds</param>
void agreementLineAddRange(QueryBuildDataSource _agreementLineQbds)
{
    // no filter on itemId as we are using Category
    _agreementLineQbds.addRange(fieldNum(AgreementLine, Category)).value(SysQuery::valueNot(0));
}

/// <summary>
/// gets the commitment type for this agreement line search.
/// </summary>
/// <returns>CommitmentType</returns>
protected CommitmentType getCommitmentType()
{
    return CommitmentType::ProductRootCategory;
}
